'use client';
import { HexColorPicker, HexColorInput } from 'react-colorful';
import { useState } from 'react';

const presets = ['#0EA5E9','#22C55E','#F59E0B','#EF4444','#A855F7','#111827'];

export function {{component_name}}({ onChange }: { onChange: (c: string) => void }) {
  const [c, setC] = useState('#0EA5E9');
  function update(v: string) { setC(v); onChange(v); }
  return (
    <div>
      <HexColorPicker color={c} onChange={update} />
      <HexColorInput color={c} onChange={update} prefixed />
      <div style={{ display:'flex', gap:6, marginTop:8 }}>
        {presets.map(p => <button key={p} onClick={() => update(p)} style={{ background:p, width:20, height:20, borderRadius:4 }} />)}
      </div>
    </div>
  );
}
